alertDetailsOverride.alertDescriptionFormat:
A single token ({{TokenType}}) belonging to {{UserPrincipalName}} was presented successfully
{{Uses}} times from {{IPs}} IP addresses across {{Countries}} countries within {{SpanMinutes}}
minutes. {{Assessment}}

Honeytoken account {{Account}} was involved in authentication activity observed by {{Source}}
({{Outcome}}) from host {{Host}} / {{IPAddress}} {{Location}}. No legitimate process
authenticates as this identity.

{{UserPrincipalName}} matches the generic/service account naming pattern and performed an
interactive logon from {{Host}}, which it has not been seen on in the preceding baseline.
It was already known on {{KnownHosts}} other hosts. {{Assessment}}

properties.query:
// --- tuning -------------------------------------------------------------
// MinAccountsPerFactor  3 is the intended setting. Drop to 2 only if you have
//   already eliminated admin//priv account pairs, or this will be all noise.
// BaselineWindow  the longest window the scheduled-rule engine allows is 14d.
//   Factors bound to a third account more than 14 days apart are caught by the
//   Credential Hygiene tab in the workbook, not by this rule.
let DetectionWindow      = 1h;
let BaselineWindow       = 14d;
let MinAccountsPerFactor = 3;
let registrations = materialize(
    AuditLogs
    | where TimeGenerated > ago(BaselineWindow)
    | where OperationName has_any ("security info", "StrongAuthentication", "authentication method", "Update user")
    | extend Target = tolower(tostring(TargetResources[0].userPrincipalName))
    | where isnotempty(Target)
    | mv-expand mp = TargetResources[0].modifiedProperties
    | extend PropName = tostring(mp.displayName), NewVal = tostring(mp.newValue)
    | where PropName has_any ("PhoneNumber", "AlternativePhoneNumber", "StrongAuthenticationUserDetails",
                              "StrongAuthenticationPhoneAppDetail", "Email", "VoiceOnlyPhoneNumber")
    | extend Raw = replace_string(replace_string(replace_string(NewVal, '"', ''), '[', ''), ']', '')
    | extend Method = trim(@"[\s\\]+", Raw)
    | where isnotempty(Method) and Method !in ("", "null", "[]")
    | extend MethodType = case(PropName has "PhoneApp", "Authenticator device",
                               PropName has "Phone",    "Phone number",
                               PropName has "Email",    "Email address",
                               PropName)
    | extend Actor = tolower(tostring(InitiatedBy.user.userPrincipalName))
    | project TimeGenerated, Target, Actor, MethodType, Method, OperationName, Result
);
// the account whose registration was most recent for each factor, resolved in
// its own step - arg_max alongside other aggregates would prefix its output
// columns and silently break the entity mapping
let latestPerFactor = registrations
    | summarize arg_max(TimeGenerated, Target, MethodType) by Method
    | project Method, LatestTarget = Target, LatestType = MethodType;
// factors whose account count reached the threshold, where the most recent
// registration landed in this run's window - so the alert fires on the change
registrations
| summarize AccountsSharing = dcount(Target),
            Accounts        = make_set(Target, 25),
            Registrations   = count(),
            Actors          = make_set_if(Actor, isnotempty(Actor), 10),
            FirstSeen       = min(TimeGenerated),
            LastSeen        = max(TimeGenerated)
    by Method
| where AccountsSharing >= MinAccountsPerFactor
| where LastSeen > ago(DetectionWindow)
| join kind=inner latestPerFactor on Method
| extend Assessment = case(AccountsSharing >= 5, "One factor now controls five or more accounts - a single person can complete MFA for all of them",
                           "One factor now controls three or more accounts - past the point where an admin second-account pair explains it")
| extend UserPrincipalName = LatestTarget,
         MethodType        = LatestType,
         AccountName       = tostring(split(LatestTarget, "@")[0]),
         AccountUPNSuffix  = tostring(split(LatestTarget, "@")[1])
| extend SpanDays = round(todouble(datetime_diff('hour', LastSeen, FirstSeen)) / 24.0, 1)
| project TimeGenerated = LastSeen, UserPrincipalName, AccountName, AccountUPNSuffix,
          MethodType, Method, AccountsSharing, Assessment, Accounts, Registrations,
          Actors, SpanDays, FirstSeen, LastSeen
| sort by AccountsSharing desc

// --- tuning -------------------------------------------------------------
// MinTargetDevices  5 per hour is a deliberate floor. Lower it to 3 in a small
//   estate. Raise it if a management tool legitimately sweeps the fleet and you
//   would rather exclude the pattern than the account.
// ExcludedAccounts  name the management and imaging accounts here rather than
//   raising the threshold, so a genuine credential sweep still surfaces.
let DetectionWindow   = 1h;
let MinTargetDevices  = 5;
let ExcludedAccounts  = dynamic(["none-such-account"]);
let BuiltInNonHuman   = dynamic(["system", "local service", "network service", "anonymous logon",
                                 "dwm-1", "dwm-2", "umfd-0", "umfd-1"]);
DeviceLogonEvents
| where TimeGenerated > ago(DetectionWindow)
| where ActionType == "LogonSuccess"
| where LogonType in ("Network", "RemoteInteractive", "Batch", "Service")
| where IsLocalAdmin == true
| where isnotempty(RemoteIP) or isnotempty(RemoteDeviceName)
| where isnotempty(AccountName)
| extend AccountNameLower = tolower(AccountName)
| where AccountNameLower !in (BuiltInNonHuman)
| where AccountNameLower !in (ExcludedAccounts)
// A local account authenticates against the SAM of the machine itself, so its
// account domain is that machine's own short name. A domain account carries the
// NetBIOS domain instead. This comparison is what separates the two; matching on
// "no dot in the domain" does not, because NetBIOS domain names have no dot.
| extend DeviceShortName = tolower(tostring(split(DeviceName, ".")[0]))
| where tolower(AccountDomain) == DeviceShortName
// Group by the account NAME alone, never by domain\name. For a local account the
// domain component is the machine, so grouping on it would place every host in
// its own bucket and the fan-out this rule exists to find could never appear.
// The local SID varies per machine for the same reason and is collected, not keyed on.
| summarize TimeGenerated   = max(TimeGenerated),
            Logons          = count(),
            TargetDevices   = dcount(DeviceName),
            SourceHosts     = dcountif(RemoteDeviceName, isnotempty(RemoteDeviceName)),
            SourceIPs       = dcountif(RemoteIP, isnotempty(RemoteIP)),
            DistinctSids    = dcountif(AccountSid, isnotempty(AccountSid)),
            TargetList      = make_set(DeviceName, 25),
            SourceList      = make_set_if(RemoteDeviceName, isnotempty(RemoteDeviceName), 25),
            SourceIPList    = make_set_if(RemoteIP, isnotempty(RemoteIP), 25),
            LogonTypes      = make_set(LogonType, 6),
            FirstSeen       = min(TimeGenerated)
    by AccountName = AccountNameLower
| where TargetDevices >= MinTargetDevices
| extend Assessment = case(TargetDevices >= 20, "Local admin credential used across the estate - identical local password fleet-wide, and something is exercising it",
                           TargetDevices >= 10, "Local admin credential sprayed across many hosts - classic shared-local-password lateral movement",
                           "Local admin credential reused across several hosts within the hour")
| extend Pattern = case(SourceHosts <= 1, "Single source host - consistent with a management sweep, confirm the tool and schedule",
                        SourceHosts >= 5, "Many source hosts - the credential itself is circulating, not one tool using it",
                        "Few source hosts - verify each is an administrative jump point")
// DistinctSids > 1 confirms these really are separate per-machine local accounts
// sharing a name and a secret, rather than one account seen repeatedly.
| extend SidEvidence = iff(DistinctSids > 1,
                           strcat(tostring(DistinctSids), " distinct local SIDs - separate SAM accounts sharing a name and secret"),
                           "Single SID - one account, verify whether the domain filter admitted a domain principal")
| extend FirstTargetHost = tostring(TargetList[0]),
         FirstSourceIP   = tostring(SourceIPList[0])
| project TimeGenerated, AccountName, Assessment, Pattern, SidEvidence,
          TargetDevices, SourceHosts, SourceIPs, DistinctSids, Logons, LogonTypes,
          TargetList, SourceList, SourceIPList, FirstTargetHost, FirstSourceIP, FirstSeen
| sort by TargetDevices desc

alertDetailsOverride.alertDescriptionFormat:
Local administrator account "{{AccountName}}" authenticated over the network to {{TargetDevices}}
distinct devices from {{SourceHosts}} source hosts within the detection window.
{{Assessment}} {{Pattern}} {{SidEvidence}}
